                </span>`,
            )}
            <span class="grow"></span>
            ${
                others.length > 0 &&
                html`<button class="link small" onClick=${() => setHanding(!handing)}>
                    ${t("Hand over…")}
                </button>`
            }
            <button class="link small" onClick=${() => run("release")}>${t("Let go")}</button>
            ${
