    const canTake = !driverHere || me?.role === "owner";

    return html`<div class="driver-bar">
        <span class="driver-label">
            ${turns.driver === undefined ? "🚗 No one is driving" : `🚗 ${name(turns.driver)} is driving${driverHere ? "" : " (away)"}`}
        </span>
        <span class="grow"></span>
        ${
